#!/usr/bin/env bash

## Usage:
## suppose project root dir is xxx
## edit config.yml first
#> mamba activate ngs
#> bash run_cuttag.sh config.yml 
## edit xxx/samplesheet.csv (generated by previous commond)
#> bash run_cuttag.sh config.yml

set -euo pipefail

# Fail fast if no config provided
if [[ ${#@} -lt 1 ]]; then
    echo "Usage: $0 config.yml" >&2
    exit 1
fi

# ============================= Helper Functions =============================
# Get script directory (works with symlinks)
SCRIPT_DIR="$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)"

# Helper functions are located in the parent directory
HELPER_SCRIPT="${SCRIPT_DIR}/../helper.sh"
if [[ ! -f "$HELPER_SCRIPT" ]]; then
    echo "ERROR: Helper script not found: $HELPER_SCRIPT" >&2
    exit 1
fi
source "$HELPER_SCRIPT"

# ============================= Configuration Loading =============================
parse_yaml_config() {
    local config="$1"
    
    # Simple YAML parser (handles key: value pairs)
    # -g so CUSTOM_BED_REGIONS survives function return and is consumed in main()
    declare -ga CUSTOM_BED_REGIONS=()
    while IFS=': ' read -r key value || [[ -n "$key" ]]; do
        # Skip comments and empty lines
        [[ "$key" =~ ^[[:space:]]*# ]] && continue
        [[ -z "$key" ]] && continue
        
        # Remove leading/trailing whitespace and quotes; strip inline comments
        # ("threads: 12  # note" would otherwise keep "# note" as the value)
        key=$(echo "$key" | xargs)
        value=$(echo "$value" | sed 's/[[:space:]]#.*$//' | xargs | sed 's/^["'\'']\|["'\'']$//g')
        
        # Skip empty values
        [[ -z "$value" ]] && continue
        
        # Map config keys to variables
        case "$key" in
            root_dir) ROOT_DIR="$value";;
            species) SPECIES="$value" ;;
            fastq_dir) FASTQ_DIR="$value" ;;
            samplesheet) SAMPLESHEET="$value" ;;
            outdir) OUTDIR="$value" ;;
            threads) THREADS="$value" ;;
            skip_preprocess) SKIP_PREPROCESS="$value" ;;
            sort_mem_limit) SORT_MEM_LIMIT="$value" ;;
            tmp_dir) TMP_DIR_CFG="$value" ;;
            scratch_dir) SCRATCH_DIR_CFG="$value" ;;
            max_frag_length) MAX_FRAG_LENGTH="$value" ;;
            peak_caller) PEAK_CALLER="$value" ;;
            macs_parameter) MACS_PARAMETER="$value" ;;
            seacr_parameter) SEACR_PARAMETER="$value" ;;
            run_spike) RUN_SPIKE="$value" ;;
            norm_method) NORM_METHOD="$value" ;;
            heatmap_binsize) HEATMAP_BINSIZE="$value" ;;
            heatmap_max_regions) HEATMAP_MAX_REGIONS="$value" ;;
            pca_ntop) PCA_NTOP="$value" ;;
            index_rootdir) INDEX_ROOTDIR="$value" ;;
            spike_free_sf_file) SPIKE_FREE_SF_FILE="$value" ;;
            bed_region) 
                # Add custom BED regions to array
                if [[ -f "$value" ]]; then
                    CUSTOM_BED_REGIONS+=("$value")
                    log_info "Added custom BED region: $value"
                else
                    log_warn "Custom BED file not found: $value, skipped"
                fi
                ;;
        esac
    done < <(tr -d '\r' < "$config")

    # Peak file extension used by MACS3: broad -> broadPeak, otherwise narrowPeak
    if [[ "$MACS_PARAMETER" =~ --broad ]]; then
        PEAK_EXT="_peaks.broadPeak"
    else
        PEAK_EXT="_peaks.narrowPeak"
    fi
} 


# ============================= BAM Integrity Helpers =============================
# sambamba exits 0 even after fatal write errors ("Unable to write to
# stream") and appends a valid BGZF EOF on its way out, so an interrupted
# BAM can pass samtools quickcheck while missing most records or carrying
# garbage before the end ("wrong BGZF magic" at index time). quickcheck only
# inspects head and tail, so every BAM this pipeline produces or reuses is
# additionally validated by a full decompression pass (every BGZF block is
# CRC-checked) before it is trusted.

bam_valid() {
    # Fully validate a BAM file: non-empty, quickcheck-clean, and decodable
    # end to end. Usage: bam_valid <bam>
    local bam="$1"
    [[ -s "$bam" ]] || return 1
    samtools quickcheck -q "$bam" 2>/dev/null || return 1
    samtools view -c "$bam" > /dev/null 2>&1 || return 1
    return 0
}

install_bam() {
    # Copy a validated scratch BAM (and its .bai, when present) into the
    # results directory and verify the copy arrived intact: byte-for-byte
    # size match plus quickcheck. A full re-read is skipped on purpose — cp
    # already transferred every byte; truncation shows up as a size mismatch
    # or missing EOF. The destination only ever appears under its final name
    # once complete, so a crash mid-copy cannot leave a half-written BAM at
    # the path the resume logic trusts. Usage: install_bam <src> <dst>
    local src="$1" dst="$2"
    rm -f "${dst}.installing" "${dst}.installing.bai"
    cp -f "$src" "${dst}.installing" || return 1
    if [[ -s "${src}.bai" ]]; then
        cp -f "${src}.bai" "${dst}.installing.bai" || return 1
    fi
    [[ "$(stat -c '%s' "$src")" == "$(stat -c '%s' "${dst}.installing")" ]] || return 1
    samtools quickcheck -q "${dst}.installing" 2>/dev/null || return 1
    mv -f "${dst}.installing" "$dst" || return 1
    if [[ -s "${dst}.installing.bai" ]]; then
        mv -f "${dst}.installing.bai" "${dst}.bai" || return 1
    fi
    return 0
}


# ============================= Sample Processing Functions =============================
bowtie2_alignment() {
    local sample="$1"
    local clean1="$FASTP_DIR/${sample}_R1.fq.gz"
    local clean2="$FASTP_DIR/${sample}_R2.fq.gz"

    local sorted_bam="$ALIGN_DIR/${sample}.sorted.bam"
    local markdup_bam="$ALIGN_DIR/${sample}.markdup.bam"
    local flagstat_file="$ALIGN_DIR/${sample}.markdup.flagstat"

    # Heavy intermediates are written to the scratch filesystem and only
    # installed into ALIGN_DIR once fully validated (see scratch_dir in main)
    local workdir="$SCRATCH_DIR/${sample}"
    local w_sorted="$workdir/${sample}.sorted.bam"
    local w_markdup="$workdir/${sample}.markdup.bam"

    # A flagstat with plausible content proves a prior run finished this
    # sample (flagstat streams the whole BAM, so its existence implies the
    # BAM was fully readable at generation time) — reuse without re-reading
    if [[ -s "$markdup_bam" && -s "${markdup_bam}.bai" && -s "$flagstat_file" ]] \
        && grep -q "in total" "$flagstat_file"; then
        :
    elif [[ -s "$markdup_bam" && -s "${markdup_bam}.bai" ]]; then
        # BAM present but flagstat missing/empty: a previous run died
        # mid-sample. Because sambamba exits 0 on write errors, the BAM may
        # be quietly corrupt — a full-record check decides between
        # regenerating the flagstat and redoing the sample
        log_info "[$sample] Verifying existing markdup BAM (flagstat missing)"
        if bam_valid "$markdup_bam"; then
            log_info "[$sample] BAM intact — regenerating flagstat"
            sambamba flagstat -t "$THREADS" "$markdup_bam" > "$flagstat_file" \
                2>>"$ALIGN_DIR/${sample}.sambamba.log" || true
        else
            log_warn "[$sample] Existing markdup BAM is corrupt — redoing alignment"
            rm -f "$markdup_bam" "${markdup_bam}.bai" "$flagstat_file"
        fi
    fi

    if [[ ! -s "$flagstat_file" || ! -s "${markdup_bam}.bai" ]] \
        || ! grep -q "in total" "$flagstat_file"; then
        log_info "[$sample] Aligning to genome"
        rm -rf "$workdir"
        mkdir -p "$workdir"
        # Retry up to 3 times: sambamba dies silently on flaky filesystem
        # writes (9P /mnt/* mounts under WSL2), leaving unusable output.
        # A valid sorted BAM survives between attempts, so a markdup failure
        # only redoes the markdup stage, not the alignment.
        local attempt=1
        while :; do
            if [[ $attempt -gt 3 ]]; then
                die "[$sample] genome alignment failed after 3 attempts (see $ALIGN_DIR/${sample}.sambamba.log)"
            fi
            [[ $attempt -gt 1 ]] && log_warn "[$sample] alignment attempt $attempt/3"

            # Stage 1: sort
            if ! bam_valid "$w_sorted"; then
                rm -f "$w_sorted" "$w_sorted.bai"
                if bam_valid "$sorted_bam"; then
                    # Valid sorted BAM left in the results dir by an older
                    # pipeline version or an interrupted run — reuse it
                    log_info "[$sample] Reusing valid sorted BAM from a previous run"
                    mv -f "$sorted_bam" "$w_sorted" || true
                    rm -f "${sorted_bam}.bai"
                else
                    rm -f "$sorted_bam" "${sorted_bam}.bai"
                    # (stderr of each tool goes to a per-sample log instead of
                    # /dev/null so failures leave a trace; command substitution
                    # at the call site would otherwise swallow the non-zero
                    # exit of this function)
                    if ! bowtie2 -x "$BOWTIE2_INDEX" -1 "$clean1" -2 "$clean2" -p "$THREADS" --phred33 \
                        --very-sensitive --local --no-mixed --no-discordant -I 10 -X "$MAX_FRAG_LENGTH" \
                        --rg-id "$sample" --rg "SM:${sample}\tPL:ILLUMINA" \
                        2>"$ALIGN_DIR/${sample}.bowtie2.log" \
                        | sambamba view -t "$THREADS" -S -f bam /dev/stdin 2>>"$ALIGN_DIR/${sample}.sambamba.log" \
                        | sambamba sort -t "$THREADS" -m "$SORT_MEM_LIMIT" -o "$w_sorted" /dev/stdin \
                            2>>"$ALIGN_DIR/${sample}.sambamba.log"; then
                        log_warn "[$sample] sort pipeline exited non-zero (attempt $attempt)"
                    fi
                fi
                if ! bam_valid "$w_sorted"; then
                    log_warn "[$sample] sort attempt $attempt did not produce a valid BAM"
                    attempt=$((attempt + 1))
                    continue
                fi
            fi

            # Stage 2: markdup + index + flagstat (all inside scratch)
            log_info "[$sample] Marking duplicates"
            sambamba markdup -t "$THREADS" "$w_sorted" "$w_markdup" \
                2>>"$ALIGN_DIR/${sample}.sambamba.log" || true
            sambamba index -t "$THREADS" "$w_markdup" \
                2>>"$ALIGN_DIR/${sample}.sambamba.log" || true
            sambamba flagstat -t "$THREADS" "$w_markdup" > "$flagstat_file" \
                2>>"$ALIGN_DIR/${sample}.sambamba.log" || true

            if bam_valid "$w_markdup" && [[ -s "$w_markdup.bai" ]] \
                && grep -q "in total" "$flagstat_file" \
                && install_bam "$w_markdup" "$markdup_bam"; then
                rm -rf "$workdir"
                break
            fi
            log_warn "[$sample] markdup attempt $attempt did not produce a valid BAM"
            rm -f "$w_markdup" "$w_markdup.bai"
            attempt=$((attempt + 1))
        done
    fi

    # Extract statistics (hard-fail: a missing/unreadable flagstat must not
    # silently produce empty stats and an unnormalized scale factor downstream)
    local total_reads mapped_reads duplicate_reads
    total_reads=$(extract_flagstat_value "$flagstat_file" "in total" 1) \
        || die "[$sample] cannot read total reads from $flagstat_file"
    mapped_reads=$(extract_flagstat_value "$flagstat_file" "mapped (.*N/A)" 1) \
        || die "[$sample] cannot read mapped reads from $flagstat_file"
    duplicate_reads=$(extract_flagstat_value "$flagstat_file" "duplicates" 1) \
        || die "[$sample] cannot read duplicate reads from $flagstat_file"

    echo "$total_reads $mapped_reads $duplicate_reads"
}

bowtie2_alignment_spike() {
    local sample="$1"
    local clean1="$FASTP_DIR/${sample}_R1.fq.gz"
    local clean2="$FASTP_DIR/${sample}_R2.fq.gz"

    local spike_sorted_bam="$ALIGN_DIR/${sample}.spike.sorted.bam"
    local spike_flagstat="$ALIGN_DIR/${sample}.spike.sorted.flagstat"

    if [[ ! -s "$spike_flagstat" ]] || ! grep -q "in total" "$spike_flagstat"; then
        log_info "[$sample] Aligning to spike-in genome"
        local workdir="$SCRATCH_DIR/${sample}.spike"
        local w_spike="$workdir/${sample}.spike.sorted.bam"
        rm -rf "$workdir"
        mkdir -p "$workdir"
        local attempt=1
        while :; do
            if [[ $attempt -gt 3 ]]; then
                die "[$sample] spike-in alignment failed after 3 attempts (see $ALIGN_DIR/${sample}.sambamba.log)"
            fi
            [[ $attempt -gt 1 ]] && log_warn "[$sample] spike-in alignment attempt $attempt/3"

            if ! bowtie2 -x "$SPIKE_INDEX" -1 "$clean1" -2 "$clean2" -p "$THREADS" --phred33 \
                --very-sensitive --local --no-mixed --no-discordant -I 10 -X "$MAX_FRAG_LENGTH" \
                --rg-id "$sample" --rg "SM:${sample}\tPL:ILLUMINA" \
                2>"$ALIGN_DIR/${sample}.spike.bowtie2.log" \
                | sambamba view -t "$THREADS" -S -f bam /dev/stdin 2>>"$ALIGN_DIR/${sample}.sambamba.log" \
                | sambamba sort -t "$THREADS" -m "$SORT_MEM_LIMIT" \
                    -o "$w_spike" /dev/stdin 2>>"$ALIGN_DIR/${sample}.sambamba.log"; then
                log_warn "[$sample] spike-in sort pipeline exited non-zero (attempt $attempt)"
            fi

            sambamba flagstat -t "$THREADS" "$w_spike" > "$workdir/spike.flagstat" \
                2>>"$ALIGN_DIR/${sample}.sambamba.log" || true

            if bam_valid "$w_spike" && grep -q "in total" "$workdir/spike.flagstat" \
                && cp -f "$workdir/spike.flagstat" "$spike_flagstat"; then
                rm -rf "$workdir"
                rm -f "$spike_sorted_bam" "${spike_sorted_bam}.bai"
                break
            fi
            log_warn "[$sample] spike-in attempt $attempt did not produce a valid result"
            rm -f "$w_spike" "$w_spike.bai"
            attempt=$((attempt + 1))
        done
    fi

    local spike_reads
    spike_reads=$(extract_flagstat_value "$spike_flagstat" "mapped (.*N/A)" 1) \
        || die "[$sample] cannot read spike-in mapped reads from $spike_flagstat"
    echo "$spike_reads"
}

bam_filter() {
    local sample="$1"
    local markdup_bam="$ALIGN_DIR/${sample}.markdup.bam"
    local filtered_bam="$ALIGN_DIR/${sample}.filtered.bam"
    local flagstat_filtered="$ALIGN_DIR/${sample}.filtered.flagstat"

    # Rerun when either the BAM or its flagstat is missing (both are needed:
    # the flagstat alone cannot regenerate a filtered BAM that was cleaned up),
    # or when the existing BAM fails quickcheck (truncated leftover)
    if [[ ! -s "$filtered_bam" || ! -s "$flagstat_filtered" ]] \
        || ! samtools quickcheck -q "$filtered_bam" 2>/dev/null; then
        local chr_filter
        case "$SPECIES" in
            chm13|hs|mm)
                chr_filter='rname =~ "^chr([0-9]+|X|Y)$"'
                ;;
            cel)
                chr_filter='rname =~ "^(I|II|III|IV|V|X)$"'
                ;;
            fly)
                chr_filter='rname =~ "^(2[LR]|3[LR]|4|X|Y)$"'
                ;;
        esac
        if [[ -z "${chr_filter:-}" ]]; then
            log_error "[$sample] Unsupported species '$SPECIES' in bam_filter (supported: chm13, hs, mm, cel, fly)"
            exit 1
        fi
        log_info "[$sample] Filtering BAM (MAPQ≥30, proper pairs, main chromosomes)"
        # Filter into scratch and install only after validation (flaky
        # filesystem writes must not leave a corrupt BAM in the results dir)
        local workdir="$SCRATCH_DIR/${sample}.filter"
        local w_filtered="$workdir/${sample}.filtered.bam"
        rm -rf "$workdir"
        mkdir -p "$workdir"
        if ! samtools view -@ "$THREADS" -b -f 2 -q 30 -F 3852 \
            -e "$chr_filter" \
            -o "$w_filtered" "$markdup_bam"; then
            log_warn "[$sample] samtools view exited non-zero during filtering"
        fi
        if bam_valid "$w_filtered" && install_bam "$w_filtered" "$filtered_bam"; then
            rm -rf "$workdir"
        else
            rm -rf "$workdir"
            die "[$sample] BAM filtering did not produce a valid output"
        fi
        sambamba index -t "$THREADS" "$filtered_bam" \
            2>>"$ALIGN_DIR/${sample}.sambamba.log" || true
        sambamba flagstat -t "$THREADS" "$filtered_bam" > "$flagstat_filtered" \
            2>>"$ALIGN_DIR/${sample}.sambamba.log" || true
        if [[ ! -s "$flagstat_filtered" ]] || ! grep -q "in total" "$flagstat_filtered"; then
            die "[$sample] filtered flagstat is missing or unreadable: $flagstat_filtered"
        fi
    fi

    local filtered_reads
    filtered_reads=$(extract_flagstat_value "$flagstat_filtered" "mapped (.*N/A)" 1) \
        || die "[$sample] cannot read filtered reads from $flagstat_filtered"
    echo "$filtered_reads"
}

# Check a normalization method's per-sample prerequisites before running it.
# Echoes a reason string when the method must be SKIPPED for this sample;
# empty output means it can run. (Spike needs spike-in alignment results,
# SpikeFree needs the scale factor file produced by spike_free_normalization.R.)
norm_prereq() {
    local method="$1" filtered_reads="$2" spike_reads="$3"
    case "$method" in
        CPM)       [[ "$filtered_reads" -gt 0 ]] || echo "filtered reads = 0" ;;
        Spike)     [[ "$spike_reads" -gt 0 ]] || echo "no spike-in reads (is run_spike enabled?)" ;;
        SpikeFree) [[ -s "$SPIKE_FREE_SF_PATH" ]] || echo "scale factor file not found: $SPIKE_FREE_SF_PATH" ;;
        *)         echo "unknown normalization method" ;;
    esac
}

# True when every configured method's BigWig for this sample already exists
norm_bws_done() {
    local sample="$1" m
    for m in "${NORM_METHODS[@]}"; do
        [[ -s "$BIGWIG_DIR/${sample}.${m}.bw" ]] || return 1
    done
}

generate_bigwig() {
    local sample="$1" method="$2" scale_factor="$3"
    local filtered_bam="$ALIGN_DIR/${sample}.filtered.bam"
    local bigwig="$BIGWIG_DIR/${sample}.${method}.bw"

    if [[ ! -s "$bigwig" ]]; then
        log_info "[$sample] Generating BigWig ($method, scale: $scale_factor)"
        # bamCoverage writes to a temp file that is renamed only on success and
        # deleted on failure, so a `.bw` at the final path is always complete
        # (no .done markers) and a failed step leaves nothing behind.
        local bigwig_tmp="${bigwig}.tmp"
        rm -f "$bigwig_tmp"
        if ! bamCoverage -b "$filtered_bam" -o "$bigwig_tmp" \
                -p "$THREADS" --binSize 10 --scaleFactor "$scale_factor" \
                2>>"$BIGWIG_DIR/bamCoverage.log"; then
            rm -f "$bigwig_tmp"
            die "[$sample] bamCoverage failed (see $BIGWIG_DIR/bamCoverage.log)"
        fi
        mv -f "$bigwig_tmp" "$bigwig"
    fi
}


run_alignment() {
    local sample="$1" group="$2" control="$3" target="$4" fq1="$5" fq2="$6"

    # Skip if already processed (exact sample-name match — a regex/grep would
    # let "KD.1" match a "KDX1,..." row). Also require the key products to
    # still exist: a CSV row alone says nothing about later manual cleanup.
    if awk -F',' -v s="$sample" '$1 == s { found=1; exit } END { exit !found }' "$STATS_CSV"; then
        if [[ -s "$ALIGN_DIR/${sample}.filtered.bam" ]] && norm_bws_done "$sample"; then
            log_info "[$sample] Alignment completed"
            return 0
        fi
        log_warn "[$sample] Statistics row exists but BAM/BigWig missing — re-running alignment steps"
    fi

    # Alignment and marking duplicates. NOTE: use `stats=$(...)` directly —
    # `read x <<< $(...)` would swallow the non-zero exit of the substitution.
    local stats
    stats=$(bowtie2_alignment "$sample") || die "[$sample] genome alignment failed (see $ALIGN_DIR/${sample}.bowtie2.log)"
    local total_reads mapped_reads duplicate_reads
    read -r total_reads mapped_reads duplicate_reads <<< "$stats"
    local mapped_pct dup_pct
    mapped_pct=$(awk -v m="$mapped_reads" -v t="$total_reads" 'BEGIN{if(t==0){printf "0.00"} else {printf "%.2f", (m/t)*100}}')
    dup_pct=$(awk -v d="$duplicate_reads" -v t="$total_reads" 'BEGIN{if(t==0){printf "0.00"} else {printf "%.2f", (d/t)*100}}')
    log_info "[$sample] Stats - Total: $total_reads, Mapped: $mapped_reads (${mapped_pct}%), Duplicates: $duplicate_reads (${dup_pct}%)"

    # Filtering
    local filtered_reads
    filtered_reads=$(bam_filter "$sample") || die "[$sample] BAM filtering failed"
    local filtered_pct
    filtered_pct=$(awk -v d="$filtered_reads" -v t="$total_reads" 'BEGIN{if(t==0){printf "0.00"} else {printf "%.2f", (d/t)*100}}')
    log_info "[$sample] Filtered reads: $filtered_reads (${filtered_pct}%)"

    # Spike-in alignment (optional)
    local spike_reads=0
    if [[ "$RUN_SPIKE" == true ]]; then
        spike_reads=$(bowtie2_alignment_spike "$sample") || die "[$sample] spike-in alignment failed"
        local spike_pct
        spike_pct=$(awk -v d="$spike_reads" -v t="$total_reads" 'BEGIN{if(t==0){printf "0.000"} else {printf "%.3f", (d/t)*100}}')
        log_info "[$sample] Spike-in reads: $spike_reads (${spike_pct}%)"
    fi
    
    # Scale factor + BigWig for every configured normalization method (in config
    # order). A method whose prerequisites are missing is SKIPPED for this sample
    # (warning, no BigWig, no statistics row) instead of aborting the run.
    local method scale_factor prereq_err
    for method in "${NORM_METHODS[@]}"; do
        prereq_err=$(norm_prereq "$method" "$filtered_reads" "$spike_reads")
        if [[ -n "$prereq_err" ]]; then
            log_warn "[$sample] $method normalization skipped: $prereq_err"
            continue
        fi
        scale_factor=$(calculate_scale_factor "$method" "$filtered_reads" "$spike_reads" "$sample" "$SPIKE_FREE_SF_PATH") \
            || die "[$sample] $method scale factor calculation failed"
        log_info "[$sample] Normalization: $method, Scale factor: $scale_factor"

        # Generate BigWig
        generate_bigwig "$sample" "$method" "$scale_factor"

        # Append one statistics row per method (FRiP is written per-tool during
        # peak QC: 05_peak/<tool>/consensus_<target>_frip.tab via plotEnrichment).
        # Sample+method dedupe: partial re-runs (e.g. a method added to the
        # config later) must not duplicate rows already recorded.
        if ! awk -F',' -v s="$sample" -v m="$method" \
                '$1 == s && $12 == m { found=1; exit } END { exit !found }' "$STATS_CSV"; then
            printf '%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s\n' \
                "$sample" "$group" "$control" "$target" "$fq1" "$fq2" \
                "$total_reads" "$mapped_reads" "$duplicate_reads" "$filtered_reads" \
                "$spike_reads" "$method" "$scale_factor" >> "$STATS_CSV"
        fi
    done
}

# ============================= Peak Calling =============================
# Find the peak file produced by a caller for a given sample.
# Usage: discover_peak_file <tool> <sample> <tool_peak_dir> [stringency]
# Safe under `set -euo pipefail`: never relies on a failing `ls` pipeline and
# always returns 0 (empty string when no peak file exists yet).
discover_peak_file() {
    local tool="$1" sample="$2" peak_dir="$3"
    local -a globs=()
    case "$tool" in
        macs)
            # anchored glob: "${sample}*_peaks.*Peak" would let sample "S1"
            # pick up "S10_peaks.broadPeak" and pollute the consensus
            globs=("$peak_dir"/${sample}_peaks.*Peak) ;;
        seacr)
            # Prefer the peak matching the current config stringency when
            # several (.relaxed/.stringent) files coexist from previous runs
            local pref=""
            [[ -n "${4:-}" ]] && pref=".${4}"
            globs=("$peak_dir"/${sample}${pref}.bed "$peak_dir"/${sample}.*.bed)
            ;;
    esac
    local f
    for f in "${globs[@]}"; do
        [[ -f "$f" ]] && { echo "$f"; return 0; }
    done
    return 0
}

run_macs() {
    local sample="$1" group="$2" control="$3" target="$4"
    
    local filtered_bam="$ALIGN_DIR/${sample}.filtered.bam"
    local peak_file="$TOOL_PEAK_DIR/${sample}${PEAK_EXT}"
    
    if [[ ! -s "$peak_file" ]]; then
        log_info "[$sample] Running macs"
        
        # Build MACS3 arguments
        local -a macs_args=("-t" "$filtered_bam" "-f" "BAMPE" "-g" "$GSIZE" "-n" "$TOOL_PEAK_DIR/${sample}" "--keep-dup" "all")
        # Split MACS parameters string into array and append
        read -ra macs_params_arr <<< "$MACS_PARAMETER"
        macs_args+=("${macs_params_arr[@]}")
        
        if [[ -n "$control" ]]; then
            local control_bam="$ALIGN_DIR/${control}.filtered.bam"
            if [[ -f "$control_bam" ]]; then
                macs_args+=("-c" "$control_bam")
            else
                log_warn "[$sample] Control BAM not found: $control_bam"
            fi
        fi
        
        # stderr goes to a per-sample log (a bare 2>/dev/null makes macs
        # failures undebuggable); failures are recorded and reported at the end
        macs3 callpeak "${macs_args[@]}" 2>>"$TOOL_PEAK_DIR/${sample}.macs3.log" || {
            log_error "[$sample] macs3 callpeak failed (see $TOOL_PEAK_DIR/${sample}.macs3.log)"
            PIPELINE_FAILURES+=("macs3:$sample")
        }
        # Remove bulky intermediate; keep xls/summits as small useful outputs
        rm -f "$TOOL_PEAK_DIR/${sample}_control_lambda.bdg"
    else
        log_info "[$sample] Call peak completed"
    fi
}

run_seacr() {
    local sample="$1" group="$2" control="$3" target="$4"
    
    # Parse positional SEACR args: <threshold> <norm|non> <relaxed|stringent>
    read -ra seacr_params_arr <<< "$SEACR_PARAMETER"
    local threshold="${seacr_params_arr[0]:-0.01}"
    local norm_mode="${seacr_params_arr[1]:-non}"
    local stringency="${seacr_params_arr[2]:-stringent}"
    
    local peak_file="$TOOL_PEAK_DIR/${sample}.${stringency}.bed"
    if [[ -s "$peak_file" ]]; then
        log_info "[$sample] SEACR peak completed"
        return 0
    fi
    
    # SEACR needs 4-column bedgraph input derived from the filtered BAM.
    # Generated with deepTools bamCoverage (multi-threaded, raw counts;
    # equivalent signal to `bedtools genomecov -bg` but much faster).
    local tempdir="$TOOL_PEAK_DIR/.tmp_bg"
    mkdir -p "$tempdir"
    local exp_bg="$tempdir/${sample}.bg"
    local exp_tmp="$tempdir/${sample}.bg.tmp"
    # The experiment bedgraph is regenerated when missing. No upfront delete:
    # when this sample doubles as someone's control, exp_bg IS the cached
    # control bedgraph (identical bamCoverage parameters) and must be reused.
    # Control bedgraphs stay cached across samples: one IgG library serves
    # every sample of the same target, so its expensive (binSize 1) bedgraph
    # is generated once.
    rm -f "$exp_tmp"
    if [[ ! -s "$exp_bg" ]]; then
        bamCoverage -b "$ALIGN_DIR/${sample}.filtered.bam" -o "$exp_tmp" \
            --outFileFormat bedgraph --binSize 1 \
            -p "$THREADS" --minMappingQuality 0 2>>"$tempdir/bamCoverage.log" && \
            mv -f "$exp_tmp" "$exp_bg" || {
                log_error "[$sample] bamCoverage failed, skipping SEACR for this sample (see $tempdir/bamCoverage.log)"
                PIPELINE_FAILURES+=("seacr-bedgraph:$sample")
                rm -f "$exp_tmp"
                return 0
            }
    fi
    [[ -s "$exp_bg" ]] || {
        log_error "[$sample] empty bedgraph, skipping SEACR for this sample"
        PIPELINE_FAILURES+=("seacr-bedgraph:$sample")
        return 0
    }

    local -a seacr_args=("$exp_bg")
    local ctrl_bg=""
    if [[ -n "$control" ]]; then
        ctrl_bg="$tempdir/${control}.bg"
        if [[ ! -s "$ctrl_bg" ]]; then
            local ctrl_tmp="$tempdir/${control}.bg.tmp"
            bamCoverage -b "$ALIGN_DIR/${control}.filtered.bam" -o "$ctrl_tmp" \
                --outFileFormat bedgraph --binSize 1 \
                -p "$THREADS" --minMappingQuality 0 2>>"$tempdir/bamCoverage.log" && \
                mv -f "$ctrl_tmp" "$ctrl_bg" || {
                    log_error "[$sample] bamCoverage failed for control: $control"
                    PIPELINE_FAILURES+=("seacr-ctrl-bedgraph:$control")
                    rm -f "$ctrl_tmp"
                    ctrl_bg=""
                }
        fi
        if [[ -s "$ctrl_bg" ]]; then
            seacr_args+=("$ctrl_bg")
        else
            log_warn "[$sample] Control bedgraph not generated for: $control"
        fi
    fi
    # No control -> use the numeric threshold from SEACR_PARAMETER
    if [[ ${#seacr_args[@]} -eq 1 ]]; then
        seacr_args+=("$threshold")
    fi
    seacr_args+=("$norm_mode" "$stringency" "$TOOL_PEAK_DIR/${sample}")

    log_info "[$sample] Running SEACR"
    ( cd "$tempdir" && SEACR_1.3.sh "${seacr_args[@]}" ) 2>>"$tempdir/SEACR.log" || {
        log_error "[$sample] SEACR failed (see $tempdir/SEACR.log)"
        PIPELINE_FAILURES+=("seacr:$sample")
    }

    # Cleanup: delete the experiment bedgraph only when this sample is NOT
    # anyone's control (a control bedgraph stays cached for the samples that
    # reference it). NOTE: this must be the function exit path with status 0 —
    # a `[[ -n $x ]] && rm ...` ending would return 1 for no-control samples
    # and silently abort the whole pipeline under `set -e`.
    if ! awk -F',' -v s="$sample" 'NR>1 && $3 == s { found=1; exit } END { exit !found }' "$SAMPLESHEET"; then
        rm -f "$exp_bg"
    fi
    return 0
}

# ============================= Peak Consensus =============================
# Usage: run_consensus <tool>
run_consensus() {
    local tool="$1"
    local peak_dir="$PEAK_DIR/$tool/peak"
    local plot_dir="$PEAK_DIR/$tool"

    # SEACR peak filenames carry the stringency (relaxed/stringent) from config;
    # prefer the file matching the current setting when several coexist.
    local stringency=""
    if [[ "$tool" == "seacr" ]]; then
        read -ra seacr_params_arr <<< "$SEACR_PARAMETER"
        stringency="${seacr_params_arr[2]:-stringent}"
    fi

    # Collect samples by target
    declare -A target_peaks
    declare -a all_peak_files
    local n_targets=0

    while IFS=, read -r sample group control target fq1 fq2 || [[ -n "${sample:-}" ]]; do
        [[ "$sample" == "sample" ]] && continue
        [[ -z "$sample" ]] && continue

        local peak_file
        peak_file=$(discover_peak_file "$tool" "$sample" "$peak_dir" "$stringency")
        [[ ! -f "$peak_file" ]] && continue

        all_peak_files+=("$peak_file")

        if [[ -n "$target" ]]; then
            if [[ -z "${target_peaks[$target]:-}" ]]; then
                target_peaks[$target]="$peak_file"
                n_targets=$((n_targets + 1))
            else
                target_peaks[$target]="${target_peaks[$target]} $peak_file"
            fi
        fi
    done < <(tail -n +2 "$SAMPLESHEET" | tr -d '\r')

    if [[ ${#all_peak_files[@]} -eq 0 ]]; then
        log_warn "[$tool] No peak files found for any sample (no peaks called?)"
        return 0
    fi

    if [[ "$n_targets" -eq 0 ]]; then
        log_warn "[$tool] ${#all_peak_files[@]} peak file(s) found, but no sample has a 'target' in $SAMPLESHEET"
        log_warn "        → consensus peaks / FRiP / per-target heatmaps are skipped"
        log_warn "        → fill the 'target' column and re-run to enable them"
        return 0
    fi

    # Create consensus for each target
    for target in "${!target_peaks[@]}"; do
        local -a peaks=()
        read -ra peaks <<< "${target_peaks[$target]}"
        # echo "$target: ${peaks[@]}"

        if [[ ${#peaks[@]} -eq 0 ]]; then
            log_warn "No peak files for target: $target"
            continue
        fi

        local consensus_bed="${plot_dir}/consensus_${target}.bed"
        if [[ ! -s "$consensus_bed" ]]; then
            log_info "[$tool][$target] Make UNION consensus (region present in ANY sample) from ${#peaks[@]} samples"
            # log_info "Samples: ${peaks[@]}"
            merge_peakfiles --input-peaks "${peaks[*]}" --output-bed "$consensus_bed" --chrom-size "$CHROM_SIZES" || \
                {
                    log_warn "[$tool] Failed to create consensus for: $target"
                    continue
                }
        else
            log_info "[$tool][$target] Consensus peak completed"
        fi
    done

    # Create consensus for all samples, only if N target > 1
    if [[ "$n_targets" -gt 1 ]] && [[ ! -s "${plot_dir}/consensus_all.bed" ]]; then
        local consensus_bed="${plot_dir}/consensus_all.bed"
        log_info "[$tool] Creating consensus peaks for: all (${#all_peak_files[@]} samples)"
        merge_peakfiles --input-peaks "${all_peak_files[*]}" --output-bed "$consensus_bed" --chrom-size "$CHROM_SIZES" || \
            log_warn "[$tool] Failed to create consensus for: all"
    fi
}



calculate_frip() {
    local prefix="$1"
    local consensus_bed="$2"
    local outdir="$3"
    shift 3

    local -a bam_array=("$@")
    if [[ ${#bam_array[@]} -eq 0 || ! -f "$consensus_bed" ]]; then
        return 0
    fi
    local -a name_array=()
    for bam in "${bam_array[@]}"; do
        name_array+=("$(basename "$bam" .filtered.bam)")
    done
    
    local frip_tab="$outdir/consensus_${prefix}_frip.tab"
    local frip_plot="$outdir/consensus_${prefix}_frip.pdf"
    if [[ ! -s "$frip_tab" ]]; then
        log_info "[QC] Computing FRiP: $prefix"
        plotEnrichment -p "$THREADS" -b "${bam_array[@]}" \
            --BED "$consensus_bed" --labels "${name_array[@]}" --outRawCounts "$frip_tab" --extendReads \
            --plotFile "$frip_plot" --plotTitle "FRiP - $prefix (Consensus Peaks)" >/dev/null \
            || { log_error "[QC] plotEnrichment (FRiP) failed for: $prefix"; PIPELINE_FAILURES+=("frip:$prefix"); }
    fi
}

profile_heatmap() {
    local prefix="$1"
    local bed_file="$2"
    local type="$3"
    local outdir="$4"
    local method="$5"
    shift 5

    local -a bw_array=("$@")
    if [[ ${#bw_array[@]} -eq 0 || ! -f "$bed_file" ]]; then
        return 0
    fi
    local -a name_array=()
    for bw in "${bw_array[@]}"; do
        name_array+=("$(basename "$bw" .${method}.bw)")
    done
        
    local bed_name=$(basename "$bed_file" .bed)
    log_info "[Heatmap QC] $prefix ($type) over $bed_name"
    
    # Subsample large BED files to bound matrix memory usage
    local region_count=$(wc -l < "$bed_file")
    local heatmap_bed="$bed_file"
    if [[ -n "$HEATMAP_MAX_REGIONS" && "$region_count" -gt "$HEATMAP_MAX_REGIONS" ]]; then
        log_warn "[Heatmap QC] $bed_name has $region_count regions, subsampling to $HEATMAP_MAX_REGIONS (fixed seed)"
        heatmap_bed="$outdir/${bed_name}_${prefix}_subsampled_${HEATMAP_MAX_REGIONS}.bed"
        if [[ ! -s "$heatmap_bed" ]]; then
            # deterministic subsample: 'yes' provides a reproducible random source
            shuf --random-source=<(yes | head -c 10000000) -n "$HEATMAP_MAX_REGIONS" "$bed_file" \
                | sort -k1,1 -k2,2n > "$heatmap_bed"
        fi
    fi
    
    # TSS heatmap
    if [[ "$type" == "tss" || "$type" == "both" ]]; then
        local heatmap_tss="$outdir/${bed_name}_${prefix}_tss_${method}_heatmap.pdf"
        if [[ ! -s "$heatmap_tss" ]]; then
            local mat_tss="$outdir/${bed_name}_${prefix}_tss_${method}_mat.gz"
            if [[ ! -s "$mat_tss" ]]; then
                computeMatrix reference-point --referencePoint TSS -S "${bw_array[@]}" -R "$heatmap_bed" \
                    -o "$mat_tss" -p "$THREADS" -b 3000 -a 3000 --binSize "$HEATMAP_BINSIZE" --skipZeros \
                    --samplesLabel "${name_array[@]}" --quiet >/dev/null \
                    || { log_error "[Heatmap QC] computeMatrix (TSS) failed: $bed_name/$prefix"; PIPELINE_FAILURES+=("computeMatrix:$prefix"); }
            fi
            if [[ -s "$mat_tss" ]]; then
                plotHeatmap -m "$mat_tss" -out "$heatmap_tss" --colorMap Blues >/dev/null \
                    || { log_error "[Heatmap QC] plotHeatmap (TSS) failed: $bed_name/$prefix"; PIPELINE_FAILURES+=("plotHeatmap:$prefix"); }
            fi
        fi
    fi

    # Center heatmap
    if [[ "$type" == "center" || "$type" == "both" ]]; then
        local heatmap_center="$outdir/${bed_name}_${prefix}_center_${method}_heatmap.pdf"
        if [[ ! -s "$heatmap_center" ]]; then
            local mat_center="$outdir/${bed_name}_${prefix}_center_${method}_mat.gz"
            if [[ ! -s "$mat_center" ]]; then
                computeMatrix reference-point --referencePoint center -S "${bw_array[@]}" -R "$heatmap_bed" \
                    -o "$mat_center" -p "$THREADS" -b 3000 -a 3000 --binSize "$HEATMAP_BINSIZE" --skipZeros \
                    --samplesLabel "${name_array[@]}" --quiet >/dev/null \
                    || { log_error "[Heatmap QC] computeMatrix (center) failed: $bed_name/$prefix"; PIPELINE_FAILURES+=("computeMatrix:$prefix"); }
            fi
            if [[ -s "$mat_center" ]]; then
                plotHeatmap -m "$mat_center" -out "$heatmap_center" --colorMap Blues >/dev/null \
                    || { log_error "[Heatmap QC] plotHeatmap (center) failed: $bed_name/$prefix"; PIPELINE_FAILURES+=("plotHeatmap:$prefix"); }
            fi
        fi
    fi
    
    # # Gene body heatmap (unchanged: always generated)
    # local heatmap_body="$MULTIQC_DIR/${bed_name}_${prefix}_body_${NORM_METHOD}_heatmap.pdf"
    # if [[ ! -s "$heatmap_body" ]]; then
    #     local mat_body="$MULTIQC_DIR/${bed_name}_${prefix}_body_${NORM_METHOD}_mat.gz"
    #     [[ ! -s "$mat_body" ]] && \
    #         computeMatrix scale-regions -S "${bw_array[@]}" -R "$bed_file" \
    #             -o "$mat_body" -p "$THREADS" -b 3000 -a 3000 --binSize "$HEATMAP_BINSIZE" \
    #             --regionBodyLength 5000 --samplesLabel "${name_array[@]}" \
    #             --quiet 2>/dev/null
    #     plotHeatmap -m "$mat_body" -out "$heatmap_body" --colorMap Blues 2>/dev/null
    # fi
}

bam_qc() {
    local -a bam_array=("$@")
    
    if [[ ${#bam_array[@]} -eq 0 ]]; then
        return 0
    fi
    
    local -a name_array=()
    for bam in "${bam_array[@]}"; do
        name_array+=("$(basename "$bam" .filtered.bam)")
    done
    
    # Fragment length distribution
    if [[ ! -s "$MULTIQC_DIR/BAM_fragment_length.pdf" ]]; then
        log_info "[BAM QC] Calculating fragment length"
        bamPEFragmentSize -b "${bam_array[@]}" -p "$THREADS" --maxFragmentLength "$MAX_FRAG_LENGTH" \
            --histogram "$MULTIQC_DIR/BAM_fragment_length.pdf" --samplesLabel "${name_array[@]}" \
            --outRawFragmentLengths "$MULTIQC_DIR/BAM_fragment_length.txt" >/dev/null \
            || { log_error "[BAM QC] bamPEFragmentSize failed"; PIPELINE_FAILURES+=("bamPEFragmentSize"); }
    fi

    # Fingerprint
    if [[ ! -s "$MULTIQC_DIR/BAM_fingerprint.pdf" ]]; then
        log_info "[BAM QC] Generating fingerprint"
        plotFingerprint -b "${bam_array[@]}" -p "$THREADS" --labels "${name_array[@]}" --skipZeros \
            --plotFile "$MULTIQC_DIR/BAM_fingerprint.pdf" --outRawCounts "$MULTIQC_DIR/BAM_fingerprint.txt" >/dev/null 2>&1 \
            || { log_error "[BAM QC] plotFingerprint failed"; PIPELINE_FAILURES+=("plotFingerprint"); }
    fi
}

bigwig_qc() {
    local prefix="$1"
    local method="$2"
    shift 2
    local -a bw_array=("$@")

    if [[ ${#bw_array[@]} -eq 0 ]]; then
        return 0
    fi

    local -a name_array=()
    for bw in "${bw_array[@]}"; do
        name_array+=("$(basename "$bw" .${method}.bw)")
    done

    local npz_file="$MULTIQC_DIR/BigWig_${prefix}_${method}.npz"

    # Compute summary
    if [[ ! -s "$npz_file" ]]; then
        log_info "[BigWig QC] Computing BigWig ($method)"
        multiBigwigSummary bins -b "${bw_array[@]}" -p "$THREADS" \
            --labels "${name_array[@]}" -o "$npz_file" 2>>"$MULTIQC_DIR/multiBigwigSummary.log" \
            || { log_error "[BigWig QC] multiBigwigSummary failed for: $prefix (see $MULTIQC_DIR/multiBigwigSummary.log)"; PIPELINE_FAILURES+=("multiBigwigSummary:$prefix"); return 0; }
    fi

    # PCA plot
    if [[ ! -s "$MULTIQC_DIR/BigWig_${prefix}_${method}_PCA.pdf" ]]; then
        log_info "[BigWig QC] Generating PCA ($method)"
        python3 "$SCRIPT_DIR/../scripts/plot_pca.py" -in "$npz_file" \
            -o "$MULTIQC_DIR/BigWig_${prefix}_${method}_PCA.pdf" \
            --outFileNameData "$MULTIQC_DIR/BigWig_${prefix}_${method}_PCA.tab" \
            --ntop "$PCA_NTOP" --plotTitle "$prefix" \
            --samplesheet "$SAMPLESHEET" >/dev/null 2>&1 || {
                log_warn "plot_pca.py failed, falling back to plotPCA"
                plotPCA -in "$npz_file" -o "$MULTIQC_DIR/BigWig_${prefix}_${method}_PCA.pdf" >/dev/null \
                    || { log_error "[BigWig QC] plotPCA failed for: $prefix"; PIPELINE_FAILURES+=("plotPCA:$prefix"); }
            }
    fi

    # Correlation heatmap
    if [[ ! -s "$MULTIQC_DIR/BigWig_${prefix}_${method}_correlation.pdf" ]]; then
        log_info "[BigWig QC] Generating Correlation ($method)"
        plotCorrelation -in "$npz_file" --corMethod spearman --whatToPlot heatmap \
            -o "$MULTIQC_DIR/BigWig_${prefix}_${method}_correlation.pdf" >/dev/null \
            || { log_error "[BigWig QC] plotCorrelation failed for: $prefix"; PIPELINE_FAILURES+=("plotCorrelation:$prefix"); }
    fi
}


run_global_qc() {
    # Collect all samples organized by target (membership decided by the
    # filtered BAM; BigWig availability is checked per normalization method
    # in the loop below)
    # Populates: TARGET_SAMPLES (associative array)
    # NOTE: `declare -g` does NOT clear already-global arrays, so reset them
    # explicitly; otherwise samples accumulate across prior peak-QC calls.
    declare -gA TARGET_SAMPLES=()
    declare -ga ALL_SAMPLES=() ALL_BAMS=() ALL_TARGETS=()
    while IFS=, read -r sample group control target fq1 fq2 || [[ -n "${sample:-}" ]]; do
        [[ "$sample" == "sample" ]] && continue
        [[ -z "$sample" ]] && continue

        local bam="$ALIGN_DIR/${sample}.filtered.bam"
        [[ ! -f "$bam" ]] && continue

        ALL_SAMPLES+=("$sample")
        ALL_BAMS+=("$bam")

        if [[ -n "$target" ]]; then
            if [[ -z "${TARGET_SAMPLES[$target]:-}" ]]; then
                TARGET_SAMPLES[$target]="$sample"
                ALL_TARGETS+=("$target")
            else
                TARGET_SAMPLES[$target]="${TARGET_SAMPLES[$target]} $sample"
            fi
        fi
    done < <(tail -n +2 "$SAMPLESHEET" | tr -d '\r')

    if [[ ${#ALL_SAMPLES[@]} -eq 0 ]]; then
        log_warn "No samples found for QC"
        return 0
    fi

    log_info "Found ${#ALL_SAMPLES[@]} samples across ${#ALL_TARGETS[@]} targets"

    # BAM-level QC (all samples, normalization-independent)
    bam_qc "${ALL_BAMS[@]}"

    # BigWig QC + region heatmaps, one round per normalization method
    local method sample bw bed_file
    for method in "${NORM_METHODS[@]}"; do
        ALL_BWS=()
        for sample in "${ALL_SAMPLES[@]}"; do
            bw="$BIGWIG_DIR/${sample}.${method}.bw"
            if [[ -s "$bw" ]]; then
                ALL_BWS+=("$bw")
            else
                log_warn "[$sample] BigWig missing (expected: $bw) — excluded from $method QC"
            fi
        done

        bigwig_qc "all_samples" "$method" "${ALL_BWS[@]}"

        for bed_file in "${BED_REGIONS[@]}"; do
            [[ -f "$bed_file" ]] && profile_heatmap "all_samples" "$bed_file" "both" "$MULTIQC_DIR" "$method" "${ALL_BWS[@]}"
        done
    done

    # MultiQC (non-peak QC stays in the multiqc/ directory)
    log_info "[Multi QC] Generating MultiQC report"
    multiqc "$OUTDIR" --force -o "$MULTIQC_DIR" --title "CUT&Tag Analysis" 2>/dev/null || true
}

# Per-tool peak QC: FRiP + heatmaps over this tool's consensus peaks,
# written directly under 05_peak/<tool>/. The single MultiQC report is
# generated later in Phase 4 (run_global_qc), scanning the whole OUTDIR.
# Usage: run_peak_qc <tool>
run_peak_qc() {
    local tool="$1"
    local peak_dir="$PEAK_DIR/$tool/peak"
    local plot_dir="$PEAK_DIR/$tool"

    # Collect samples organized by target (BAM presence decides membership,
    # same as run_global_qc; BigWigs are resolved per normalization method)
    # NOTE: `declare -g` does NOT clear already-global arrays, so reset them
    # explicitly; otherwise samples accumulate across tool calls (duplicates).
    declare -gA TARGET_SAMPLES=()
    declare -ga ALL_SAMPLES=() ALL_BAMS=() ALL_TARGETS=()
    while IFS=, read -r sample group control target fq1 fq2 || [[ -n "${sample:-}" ]]; do
        [[ "$sample" == "sample" ]] && continue
        [[ -z "$sample" ]] && continue

        local bam="$ALIGN_DIR/${sample}.filtered.bam"
        [[ ! -f "$bam" ]] && continue

        ALL_SAMPLES+=("$sample")
        ALL_BAMS+=("$bam")

        if [[ -n "$target" ]]; then
            if [[ -z "${TARGET_SAMPLES[$target]:-}" ]]; then
                TARGET_SAMPLES[$target]="$sample"
                ALL_TARGETS+=("$target")
            else
                TARGET_SAMPLES[$target]="${TARGET_SAMPLES[$target]} $sample"
            fi
        fi
    done < <(tail -n +2 "$SAMPLESHEET" | tr -d '\r')

    if [[ ${#ALL_SAMPLES[@]} -eq 0 ]]; then
        log_warn "[$tool] No samples found for peak QC"
        return 0
    fi

    # FRiP per target (BAM-based, normalization-independent)
    local target sample
    local -a target_samples=()
    for target in "${ALL_TARGETS[@]}"; do
        target_samples=()
        read -ra target_samples <<< "${TARGET_SAMPLES[$target]}"
        local -a target_bams=()
        for sample in "${target_samples[@]}"; do
            target_bams+=("$ALIGN_DIR/${sample}.filtered.bam")
        done

        local target_consensus="$plot_dir/consensus_${target}.bed"
        if [[ -f "$target_consensus" ]]; then
            calculate_frip "$target" "$target_consensus" "$plot_dir" "${target_bams[@]}"
        fi
    done

    # Heatmaps over consensus peaks, one round per normalization method
    local method bw
    for method in "${NORM_METHODS[@]}"; do
        for target in "${ALL_TARGETS[@]}"; do
            target_samples=()
            read -ra target_samples <<< "${TARGET_SAMPLES[$target]}"
            local -a target_bws=()
            for sample in "${target_samples[@]}"; do
                bw="$BIGWIG_DIR/${sample}.${method}.bw"
                [[ -s "$bw" ]] && target_bws+=("$bw")
            done
            [[ ${#target_bws[@]} -eq 0 ]] && continue

            local target_consensus="$plot_dir/consensus_${target}.bed"
            [[ -f "$target_consensus" ]] && \
                profile_heatmap "$target" "$target_consensus" "center" "$plot_dir" "$method" "${target_bws[@]}"
        done
    done

    # All-samples consensus peak QC, only if >1 target
    if [[ ${#ALL_TARGETS[@]} -gt 1 ]]; then
        local all_consensus="$plot_dir/consensus_all.bed"
        if [[ -f "$all_consensus" ]]; then
            calculate_frip "all" "$all_consensus" "$plot_dir" "${ALL_BAMS[@]}"
        fi
    fi
}


# ============================= Main Pipeline =============================
main() {
    local config_file="${1:-}"

    # Defaults for optional keys (protect against unset under `set -u`;
    # applied before parse_yaml_config because it reads PEAK_CALLER)
    SKIP_PREPROCESS="${SKIP_PREPROCESS:-false}"
    PEAK_CALLER="${PEAK_CALLER:-}"
    RUN_SPIKE="${RUN_SPIKE:-false}"
    NORM_METHOD="${NORM_METHOD:-CPM}"
    MACS_PARAMETER="${MACS_PARAMETER:-}"
    SEACR_PARAMETER="${SEACR_PARAMETER:-}"
    SORT_MEM_LIMIT="${SORT_MEM_LIMIT:-8G}"
    TMP_DIR_CFG="${TMP_DIR_CFG:-}"
    SCRATCH_DIR_CFG="${SCRATCH_DIR_CFG:-}"
    MAX_FRAG_LENGTH="${MAX_FRAG_LENGTH:-2000}"
    THREADS="${THREADS:-8}"

    # Load configuration
    parse_yaml_config "$config_file"
    
    # Parse peak_caller into a normalized tool list (comma/space separated)
    PEAK_CALLERS=()
    if [[ -n "$PEAK_CALLER" && "$PEAK_CALLER" != "null" && "$PEAK_CALLER" != "~" ]]; then
        IFS=', ' read -ra _pc_arr <<< "$PEAK_CALLER"
        for _t in "${_pc_arr[@]}"; do
            [[ -z "$_t" ]] && continue
            case "$_t" in
                macs|macs2) PEAK_CALLERS+=("macs") ;;
                seacr)      PEAK_CALLERS+=("seacr") ;;
                *)          log_warn "Unknown peak caller '$_t' ignored (supported: macs, seacr)" ;;
            esac
        done
    fi

    # Parse norm_method into a normalized list (comma/space separated), like
    # peak_caller: every method produces its own <sample>.<method>.bw BigWig
    # and its own BigWig QC / heatmaps downstream
    NORM_METHODS=()
    if [[ -n "$NORM_METHOD" && "$NORM_METHOD" != "null" && "$NORM_METHOD" != "~" ]]; then
        IFS=', ' read -ra _nm_arr <<< "$NORM_METHOD"
        for _m in "${_nm_arr[@]}"; do
            [[ -z "$_m" ]] && continue
            case "$_m" in
                CPM|Spike|SpikeFree) NORM_METHODS+=("$_m") ;;
                *) log_warn "Unknown normalization method '$_m' ignored (supported: CPM, Spike, SpikeFree)" ;;
            esac
        done
    fi
    if [[ ${#NORM_METHODS[@]} -eq 0 ]]; then
        NORM_METHODS=("CPM")
    fi
    
    # Defaults for heatmap options (if not set in config)
    HEATMAP_BINSIZE="${HEATMAP_BINSIZE:-50}"
    HEATMAP_MAX_REGIONS="${HEATMAP_MAX_REGIONS:-100000}"
    PCA_NTOP="${PCA_NTOP:-100000}"
    log_info "  Heatmap bin size: $HEATMAP_BINSIZE (max regions: $HEATMAP_MAX_REGIONS, PCA ntop: $PCA_NTOP)"

    # Check dependencies.
    # - fastqc: the FastQC step is currently disabled in helper.sh (run_preprocess)
    # - deepTools ships per-tool executables; there is no "deeptools" binary,
    #   so check every deepTools command this pipeline actually calls.
    require_commands fastp bowtie2 sambamba samtools bedtools multiqc \
        bamCoverage computeMatrix plotHeatmap multiBigwigSummary plotCorrelation \
        plotPCA bamPEFragmentSize plotFingerprint plotEnrichment

    # set path — validate root BEFORE any log file inside it is opened
    if [[ ! -d "$ROOT_DIR" ]]; then
        echo "ERROR: root_dir does not exist: $ROOT_DIR" >&2
        exit 1
    fi
    OUTDIR="$ROOT_DIR/$OUTDIR"
    FASTQ_DIR="$ROOT_DIR/$FASTQ_DIR"
    SAMPLESHEET="$ROOT_DIR/$SAMPLESHEET"
    mkdir -p "$OUTDIR"

    # Disk-backed scratch dir for tool temp files. sambamba sort/markdup spill
    # chunks into $TMPDIR, which defaults to /tmp — a small RAM-backed tmpfs on
    # many systems (WSL2: ~50% of RAM). When sorting large BAMs the tmpfs fills
    # up and the sort dies mid-stream ("Unable to write to stream"), cascading
    # into markdup/index/flagstat failures. Redirect TMPDIR next to the results
    # (config key tmp_dir overrides; relative paths are ROOT_DIR-relative).
    if [[ -n "$TMP_DIR_CFG" && "$TMP_DIR_CFG" != /* ]]; then
        TMP_DIR_CFG="$ROOT_DIR/$TMP_DIR_CFG"
    fi
    TMP_DIR="${TMP_DIR_CFG:-$OUTDIR/tmp}"
    mkdir -p "$TMP_DIR"
    export TMPDIR="$TMP_DIR" TMP="$TMP_DIR"

    # Scratch filesystem for multi-GB alignment intermediates (sorted /
    # markdup BAMs). Under WSL2 the /mnt/* Windows mounts are 9P filesystems
    # where large streamed writes intermittently fail — and sambamba exits 0
    # on those errors, so a sort/markdup can quietly produce a corrupt BAM.
    # Writing intermediates on the Linux-native filesystem avoids that;
    # finished BAMs are validated and copied into the results dir afterwards
    # (see bam_valid / install_bam). "auto" picks the native
    # HOME filesystem when running under WSL with plenty of free space,
    # falling back to TMP_DIR elsewhere. Config key scratch_dir overrides.
    if [[ -n "$SCRATCH_DIR_CFG" ]]; then
        SCRATCH_DIR="$SCRATCH_DIR_CFG"
        [[ "$SCRATCH_DIR" != /* ]] && SCRATCH_DIR="$ROOT_DIR/$SCRATCH_DIR"
    elif grep -qi microsoft /proc/version 2>/dev/null; then
        local avail_kb
        avail_kb=$(df -Pk "$HOME" 2>/dev/null | awk 'NR==2 {print $4}')
        if [[ "${avail_kb:-0}" -ge $((100 * 1024 * 1024)) ]]; then
            SCRATCH_DIR="$HOME/.cache/cuttag_scratch"
        else
            log_warn "Less than 100G free on the \$HOME filesystem — using $TMP_DIR for alignment scratch"
            SCRATCH_DIR="$TMP_DIR"
        fi
    else
        SCRATCH_DIR="$TMP_DIR"
    fi
    mkdir -p "$SCRATCH_DIR"

    # Set up logging: keep a copy of the original terminal stdout (fd3), then send
    # all output to the log file; the pipeline's own [date-time]-prefixed
    # messages are echoed to the terminal via fd3 (tool chatter stays in the
    # log only). log_* are redefined below to duplicate the message to both.
    exec 3>&1
    local log_file="$ROOT_DIR/pipeline.log"
    exec > >(cat >> "$log_file") 2>&1
    log_info() { echo "[$(date '+%Y-%m-%d %H:%M')] [INFO] $*" | tee /dev/stderr >&3; }
    log_warn() { echo "[$(date '+%Y-%m-%d %H:%M')] [WARN] $*" | tee /dev/stderr >&3; }
    log_error() { echo "[$(date '+%Y-%m-%d %H:%M')] [ERROR] $*" | tee /dev/stderr >&3; }

    # Non-fatal per-sample/per-step failures (peak calling, QC) are collected
    # here and reported with a non-zero exit at the end.
    PIPELINE_FAILURES=()
    
    log_info "============================================================"
    log_info "CUT&Tag Analysis Pipeline"
    log_info "============================================================"

    # Setup genome
    setup_genome "$SPECIES" "$INDEX_ROOTDIR"

    # Append custom BED regions (bed_region key in config.yml)
    if [[ ${#CUSTOM_BED_REGIONS[@]} -gt 0 ]]; then
        log_info "Adding ${#CUSTOM_BED_REGIONS[@]} custom BED region(s) to heatmap QC"
        BED_REGIONS+=("${CUSTOM_BED_REGIONS[@]}")
    fi

    # Check samplesheet
    if [[ ! -s "$SAMPLESHEET" ]]; then
        log_warn "Samplesheet not found: $SAMPLESHEET"
        log_info "Generating template samplesheet from FASTQ directory..."
        generate_samplesheet "$FASTQ_DIR" "$SAMPLESHEET"
        log_info "Please edit $SAMPLESHEET and re-run the pipeline"
        exit 0
    fi

    # Define directory paths
    FASTQC_DIR="$OUTDIR/01_fastqc"
    FASTP_DIR="$OUTDIR/02_fastp"
    ALIGN_DIR="$OUTDIR/03_bam"
    BIGWIG_DIR="$OUTDIR/04_bigwig"
    PEAK_DIR="$OUTDIR/05_peak"
    MULTIQC_DIR="$OUTDIR/multiqc"

    # Resolve the spike-free scale factor file once (consumed by norm_prereq /
    # calculate_scale_factor for SpikeFree). Config key spike_free_sf_file
    # overrides; the default lives next to the BAMs (produced by
    # spike_free_normalization.R).
    if [[ -n "${SPIKE_FREE_SF_FILE:-}" ]]; then
        SPIKE_FREE_SF_PATH="$SPIKE_FREE_SF_FILE"
        [[ "$SPIKE_FREE_SF_PATH" != /* ]] && SPIKE_FREE_SF_PATH="$ROOT_DIR/$SPIKE_FREE_SF_PATH"
    else
        SPIKE_FREE_SF_PATH="$ALIGN_DIR/SpikeFree_SF.txt"
    fi

    # Up-front availability check for methods with extra prerequisites (files
    # that only appear later are still caught per-sample by norm_prereq)
    if [[ " ${NORM_METHODS[*]} " == *" Spike "* && "$RUN_SPIKE" != "true" ]]; then
        log_warn "norm_method includes Spike but run_spike: false — Spike BigWigs will be skipped"
    fi
    if [[ " ${NORM_METHODS[*]} " == *" SpikeFree "* && ! -s "$SPIKE_FREE_SF_PATH" ]]; then
        log_warn "norm_method includes SpikeFree but scale factor file not found: $SPIKE_FREE_SF_PATH — SpikeFree BigWigs will be skipped"
    fi

    # Create directories
    create_dirs "$OUTDIR"
    
    # Initialize statistics file — one CSV shared by all methods; each sample
    # gets one row per normalization method (norm_method / scale_factor columns)
    STATS_CSV="$OUTDIR/statistics.csv"
    if [[ ! -f "$STATS_CSV" ]]; then
        log_info "Initializing statistics file: $STATS_CSV"
        cat > "$STATS_CSV" <<EOF
sample,group,control,target,fq1,fq2,total_reads,mapped_reads,duplicate_reads,filtered_reads,spike_reads,norm_method,scale_factor
EOF
    fi

    # Display configuration
    log_info "Configuration:"
    log_info "  Species: $SPECIES"
    log_info "  Samplesheet: $SAMPLESHEET"
    log_info "  Threads: $THREADS"
    log_info "  Temp dir (TMPDIR): $TMP_DIR"
    log_info "  Scratch dir (alignment): $SCRATCH_DIR"
    log_info "  Normalization: ${NORM_METHODS[*]}"
    log_info "  Peak calling: ${PEAK_CALLER:-none}"
    log_info "  Spike-in: $RUN_SPIKE"
    log_info "============================================================"
    
    # Phase 1: Pre-processing
    if [[ "$SKIP_PREPROCESS" == true ]]; then
        log_info ""
        log_info "========== Skip Pre-processing =========="
    else
        log_info ""
        log_info "========== Phase 1: Pre-processing  =========="
        create_dirs "$FASTQC_DIR" "$FASTP_DIR"
        loop_over_csv "$SAMPLESHEET" run_preprocess
    fi

    # Phase 2: Alignment
    log_info ""
    log_info "========== Phase 2: Alignment =========="
    create_dirs "$ALIGN_DIR" "$BIGWIG_DIR"
    loop_over_csv "$SAMPLESHEET" run_alignment
    
    # Phase 3: Peak Calling (per selected tool)
    if [[ ${#PEAK_CALLERS[@]} -gt 0 ]]; then
        create_dirs "$PEAK_DIR"
        for tool in "${PEAK_CALLERS[@]}"; do
            TOOL_PEAK_DIR="$PEAK_DIR/$tool/peak"
            TOOL_PLOT_DIR="$PEAK_DIR/$tool"
            create_dirs "$TOOL_PEAK_DIR" "$TOOL_PLOT_DIR"
            
            case "$tool" in
                macs)   require_commands macs3 ;;
                seacr)  require_commands SEACR_1.3.sh ;;
            esac
            
            log_info ""
            log_info "========== Phase 3: Peak Calling ($tool) =========="
            loop_over_csv "$SAMPLESHEET" "run_${tool}"
            
            log_info "========== Consensus Peaks ($tool) =========="
            run_consensus "$tool"
            
            log_info "========== Peak QC ($tool) =========="
            run_peak_qc "$tool"
        done
    fi
    
    # Phase 4: QC
    log_info ""
    log_info "========== Phase 4: QC =========="
    create_dirs "$MULTIQC_DIR"
    run_global_qc

    # Final failure summary: individual steps were allowed to continue, but the
    # overall exit status must reflect that something went wrong.
    if [[ ${#PIPELINE_FAILURES[@]} -gt 0 ]]; then
        log_error "Pipeline finished WITH FAILURES (${#PIPELINE_FAILURES[@]}):"
        local f
        for f in "${PIPELINE_FAILURES[@]}"; do
            log_error "  - $f"
        done
        log_error "See $ROOT_DIR/pipeline.log for details."
        exit 1
    fi

    log_info ""
    log_info "============================================================"
    log_info "Pipeline completed successfully!"
    log_info "============================================================"
}


# ============================= Entry Point =============================
main "$@"
